#!/usr/bin/env bash
# Generated by Confys Local. Builds a service image, loads it into minikube, and pins its tag in Git.
#
#   scripts/release.sh <service>              build, load, bump the tag in the local overlay (no commit)
#   scripts/release.sh <service> --load-only  build and load the tag already pinned in Git (used by make up)
#   scripts/release.sh <service> --commit     also commit the tag bump
#   scripts/release.sh <service> --push       commit and push (uses the gh credential helper, no git config change)
#
# The tag is the short SHA of the last commit that touched services/<service>: immutable, never re-pushed.
# Order is enforced: build, load, confirm the image in the cluster, only then change Git.
set -euo pipefail
cd "$(dirname "$0")/.."

PROFILE=onboarding
SERVICE="${1:?usage: release.sh <service> [--load-only|--commit|--push]}"
MODE="${2:-bump}"
case "$SERVICE" in service-b|service-a) ;; *) echo "Unknown service: $SERVICE" >&2; exit 1;; esac

OVERLAY="deploy/overlays/local/$SERVICE/kustomization.yaml"
TAG="$(git log -1 --format=%h -- "services/$SERVICE")"
[ -n "$TAG" ] || { echo "services/$SERVICE has no commit yet" >&2; exit 1; }
git diff --quiet HEAD -- "services/$SERVICE" || { echo "Uncommitted changes in services/$SERVICE: commit them first" >&2; exit 1; }

PINNED="$(sed -n 's/^ *newTag: *//p' "$OVERLAY")"
if [ "$MODE" = "--load-only" ] && [ "$PINNED" != "$TAG" ]; then
  echo "Overlay pins $PINNED but services/$SERVICE is at $TAG: run 'make release SERVICE=$SERVICE'" >&2
  exit 1
fi

if [ -z "${JAVA_HOME:-}" ] && [ -x /usr/libexec/java_home ]; then
  JAVA_HOME="$(/usr/libexec/java_home -v 21)"
fi
export JAVA_HOME

echo "Building $SERVICE:$TAG"
if [ "${SKIP_TESTS:-0}" = "1" ]; then
  mvn -q -f "services/$SERVICE/pom.xml" package -DskipTests
else
  mvn -q -f "services/$SERVICE/pom.xml" package
fi
docker build -q -t "$SERVICE:$TAG" "services/$SERVICE" >/dev/null

minikube -p "$PROFILE" image load "$SERVICE:$TAG"
minikube -p "$PROFILE" image ls | grep -q "$SERVICE:$TAG" || { echo "$SERVICE:$TAG is not in the cluster" >&2; exit 1; }
echo "$SERVICE:$TAG is loaded in minikube"

[ "$MODE" = "--load-only" ] && exit 0

perl -pi -e "s/newTag: .*/newTag: $TAG/" "$OVERLAY"
echo "Pinned $SERVICE:$TAG in $OVERLAY"

if [ "$MODE" = "--commit" ] || [ "$MODE" = "--push" ]; then
  git add "$OVERLAY"
  git commit -m "deploy($SERVICE): $TAG"
fi
if [ "$MODE" = "--push" ]; then
  git -c credential.helper= -c credential.helper='!gh auth git-credential' push origin HEAD
fi
